 12→typealias SecureBackupKeyBackupScreenViewModelType = StateStoreViewModelV2<SecureBackupKeyBackupScreenViewState, SecureBackupKeyBackupScreenViewAction>
 13→
 14→class SecureBackupKeyBackupScreenViewModel: SecureBackupKeyBackupScreenViewModelType, SecureBackupKeyBackupScreenViewModelProtocol {
 15→    private let secureBackupController: SecureBackupControllerProtocol
 16→    private let userIndicatorController: UserIndicatorControllerProtocol?
 17→    
 18→    private var actionsSubject: PassthroughSubject<SecureBackupKeyBackupScreenViewModelAction, Never> = .init()
 19→    var actions: AnyPublisher<SecureBackupKeyBackupScreenViewModelAction, Never> {
 20→        actionsSubject.eraseToAnyPublisher()
 21→    }
 22→
 23→    init(secureBackupController: SecureBackupControllerProtocol, userIndicatorController: UserIndicatorControllerProtocol?) {
 24→        self.secureBackupController = secureBackupController
 25→        self.userIndicatorController = userIndicatorController
 26→        
 27→        super.init(initialViewState: .init(mode: secureBackupController.keyBackupState.value.viewMode))
 28→        
 29→        secureBackupController.keyBackupState
 30→            .receive(on: DispatchQueue.main)
 31→            .sink { [weak self] state in
 32→                switch state {
 33→                case .disabling, .enabling, .unknown:
 34→                    self?.showLoadingIndicator()
 35→                default:
 36→                    self?.dismissLoadingIndicator()
 37→                }
 38→            }
 39→            .store(in: &cancellables)
 40→    }
 41→    
 42→    // MARK: - Public
 43→    
 44→    override func process(viewAction: SecureBackupKeyBackupScreenViewAction) {
 45→        MXLog.info("View model: received view action: \(viewAction)")
 46→        
 47→        switch viewAction {
 48→        case .cancel:
 49→            actionsSubject.send(.done)
 50→        case .toggleBackup:
 51→            guard secureBackupController.keyBackupState.value == .enabled else {
 52→                fatalError("Tried disabling backup when not enabled")
 53→            }
 54→            
 55→            state.bindings.alertInfo = .init(id: .init(),
 56→                                             title: L10n.screenKeyBackupDisableConfirmationTitle,
 57→                                             message: L10n.screenKeyBackupDisableConfirmationDescription,
 58→                                             primaryButton: .init(title: L10n.screenKeyBackupDisableConfirmationActionTurnOff, role: .destructive) { [weak self] in
 59→                                                 self?.disableBackup()
 60→                                             },
 61→                                             secondaryButton: .init(title: L10n.actionCancel, role: .cancel, action: nil))
 62→        }
 63→    }
 64→    
 65→    // MARK: - Private
 66→        
 67→    private func disableBackup() {
 68→        Task {
 69→            switch await secureBackupController.disable() {
 70→            case .success:
 71→                actionsSubject.send(.done)
 72→            case .failure(let error):
 73→                MXLog.error("Failed disabling key backup with error: \(error)")
 74→                state.bindings.alertInfo = .init(id: .init())
 75→            }
 76→            
 77→            dismissLoadingIndicator()
 78→        }
 79→    }
 80→    
 81→    private static let loadingIndicatorIdentifier = "\(SecureBackupKeyBackupScreenViewModel.self)-Loading"
 82→    
 83→    private func showLoadingIndicator() {
 84→        userIndicatorController?.submitIndicator(.init(id: Self.loadingIndicatorIdentifier, type: .modal, title: L10n.commonLoading, persistent: true))
 85→    }
 86→    
 87→    private func dismissLoadingIndicator() {
 88→        userIndicatorController?.retractIndicatorWithId(Self.loadingIndicatorIdentifier)
 89→    }
 90→}
 91→
 92→extension SecureBackupKeyBackupState {
 93→    var viewMode: SecureBackupKeyBackupScreenViewMode {
 94→        guard self == .enabled else {
 95→            fatalError("Invalid key backup state")
 96→        }
 97→        
 98→        return .disableBackup
 99→    }
100→}
